pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0); }
    function testFuzz_property(uint256 amount, address beneficiary) public {
        vm.assume(amount > 0);
        vm.assume(beneficiary != address(0));
        address underlying = address(c.mAsset());
        deal(underlying, address(this), amount);
        // Approve C to transfer underlying
        IERC20(underlying).approve(address(c), amount);

        uint256 creditsBefore = c.imBalances(beneficiary);
        c.supplyTokenTo(amount, beneficiary);
        uint256 creditsAfter = c.imBalances(beneficiary);

        uint256 exchangeRate = c.savings().exchangeRate();
        uint256 expectedCredits = (amount * 1e18) / exchangeRate;
        assertEq(creditsAfter - creditsBefore, expectedCredits);
    }
}

